// TH16 v1.00a Extra 双中Boss 符卡3「弾舞「二つ目の台風」」
// Source: st07mbs.ecl.txt MBossCard3:431-474 / MBossCard3_at:476-501 / MBossCard3_at1B:503-528
//         st07mbs2.ecl.txt MBossBCard3:271-313 / MBossCard3B_at:386-410 / MBossCard3B_at1B:412-436
// Entry: previous card's interrupt; both mid-bosses created on the same frame (st07.ecl.txt:1580-1581).
// Type 11 (TALISMAN) reuses the approved identical TH16 alias slot (bullet-types.md).

const TH16_TALISMAN: int = 528;

const TIME_LIMIT: int = 3724;
const OPENING_BUFFER: int = 120;

// MBossCard3_at: STEP a=60 c=0 r=+0.5235988rad, then a=60 c=0 r=-2.0943952rad;
// s<=-999990 keeps the saved speed (3.0) restored at each segment boundary.
xformdef MB_A_STEP {
    offscreen_keep(180);
    @60 step_speed(0fx, 60);
    turn(30deg);
    set_speed(3fx);
    @60 step_speed(0fx, 60);
    turn(-120deg);
    set_speed(3fx);
}

// MBossCard3_at1B: same STEP with r=-0.5235988rad, then +2.0943952rad.
xformdef MB_A1B_STEP {
    offscreen_keep(180);
    @60 step_speed(0fx, 60);
    turn(-30deg);
    set_speed(3fx);
    @60 step_speed(0fx, 60);
    turn(120deg);
    set_speed(3fx);
}

// MBossCard3B_at: ANGLE_ACCEL a=600, r=0.012 px/frame^2, s=0.014959965 rad/frame.
// 0.014959965 rad * 65536/(2*pi) = 156 BAM/frame.
xformdef MB_B_SPIN_POS {
    offscreen_keep(240);
    set_ang_vel(156bam);
    set_accel(0.012fx);
    @600 add_speed(0fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// MBossCard3B_at1B: ANGLE_ACCEL with s=-0.014959965 rad/frame.
xformdef MB_B_SPIN_NEG {
    offscreen_keep(240);
    set_ang_vel(-156bam);
    set_accel(0.012fx);
    @600 add_speed(0fx);
    set_ang_vel(0deg);
    set_accel(0fx);
}

// MBossCard3_at. etAim mode 3 fixed ring, 24x1, etSpeed(3.0,1.2) with one layer -> 3.0.
// etDist 20 minus ANIM a=1 retreat 4*3.0 -> net 8 px along each bullet angle.
sub volley_a(count: int) {
    var a: angle = 90deg;
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 24, 1);
    sh_speed(0, 3fx, 0fx);
    sh_dist(0, 8fx);
    sh_xform(0, MB_A_STEP);
    var i: int = 0;
    while i < count {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(20);
        a = a - 2deg;
        i = i + 1;
    }
}

// MBossCard3_at1B: same ring, opposite STEP turn order.
sub volley_a1b(count: int) {
    var a: angle = 90deg;
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 24, 1);
    sh_speed(0, 3fx, 0fx);
    sh_dist(0, 8fx);
    sh_xform(0, MB_A1B_STEP);
    var i: int = 0;
    while i < count {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(20);
        a = a + 2deg;
        i = i + 1;
    }
}

// MBossCard3B_at. etAim mode 3, 24x1, etSpeed(2.0,1.2) -> 2.0.
// etDist 20 minus ANIM a=1 retreat 4*2.0 -> net 12 px.
sub volley_b(count: int) {
    var a: angle = 90deg;
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 10);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 24, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 12fx);
    sh_xform(0, MB_B_SPIN_POS);
    var i: int = 0;
    while i < count {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(20);
        a = a - 2deg;
        i = i + 1;
    }
}

// MBossCard3B_at1B: opposite ANGLE_ACCEL direction.
sub volley_b1b(count: int) {
    var a: angle = 90deg;
    sh_reset(0);
    sh_sprite(0, TH16_TALISMAN, 10);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 24, 1);
    sh_speed(0, 2fx, 0fx);
    sh_dist(0, 12fx);
    sh_xform(0, MB_B_SPIN_NEG);
    var i: int = 0;
    while i < count {
        sh_angle(0, a, 0deg);
        sh_fire(0);
        wait(20);
        a = a + 2deg;
        i = i + 1;
    }
}

// MBoss entry state: boxes from st07mbs.ecl.txt:22-23 / st07mbs2.ecl.txt:87-88.
// Previous card's exit position is not in this task's material, so the entry uses the
// shared init's end position (80,128)/(-80,128); the card's own 60-frame opening move is kept.
async sub boss_a() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    move_to(60, -48fx, 160fx, EASE_QUAD_OUT);
    wait(60);
    // 7 full 500-frame cycles, then the 2 volleys before the source's 3600-frame interrupt.
    for cycle in 0..7 {
        volley_a(8);
        wait(90);
        volley_a1b(8);
        wait(90);
    }
    volley_a(2);
}

async sub boss_b() {
    set_invuln(65535);
    set_hurtbox(24fx);
    set_hitbox(20fx);
    move_to(60, 48fx, 160fx, EASE_QUAD_OUT);
    wait(60);
    for cycle in 0..7 {
        volley_b(8);
        wait(90);
        volley_b1b(8);
        wait(90);
    }
    volley_b(2);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(80fx, 128fx, 1900, 0, 0, 0, boss_a);
    _ = spawn_enemy(-80fx, 128fx, 1900, 0, 0, 0, boss_b);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    spell_begin(0, 108, pattern, TIME_LIMIT, 0, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
